"""
TTLock integration — mint an offline keypad PIN for a booking's gate.

Ported from the HiringGate POC (TTLock Open Platform cloud API v3). The PIN is a
"random"/offline passcode: generated by TTLock's algorithm, validated by the lock
offline against its own real-time clock, so it needs NO gateway and NO internet at
the court. It is hour-granular (a 19:20 start becomes 19:00).

Design, mirroring the Pelecard service:
  - Per-club config lives in ENV only (TTLOCK_<CLUBID>_*), so enabling/disabling a
    club is an env change — no code, and only one nullable DB column (court_order.
    gate_code) ever touched. A club with no config is simply skipped.
  - Every public entry point NEVER raises: on any failure it logs and returns None,
    exactly like the email service, so TTLock can never break a booking or payment.

TTLock quirks handled (see the POC's ttlock/client.ts):
  - OAuth2 "resource owner password": the TTLock *app* account + md5(password).
    Tokens last ~90 days and can be refreshed.
  - Every call carries clientId, accessToken and `date` (ms). TTLock rejects a call
    (errcode 80000) if `date` is >5 min off its clock — keep NTP on the server.
  - Failures come back as HTTP 200 with a non-zero `errcode`, not an HTTP error.
  - Token errors 10003/10004/10011 mean "log in again".
"""
import logging
import os
import threading
import time
from datetime import datetime, timedelta
from hashlib import md5 as _md5
from zoneinfo import ZoneInfo

import httpx

from app.services.payment import _env_file_values  # same .env/real-env loader as Pelecard

logger = logging.getLogger("tennisline.ttlock")

CLUB_TZ = ZoneInfo("Asia/Jerusalem")
_HOUR_MS = 3_600_000
_DEFAULT_API_BASE = "https://euapi.ttlock.com"
_DEFAULT_EARLY_ENTRY_MIN = 30
_TOKEN_ERRORS = {10003, 10004, 10011}
_REFRESH_MARGIN_S = 7 * 24 * 3600  # refresh well before the ~90-day expiry


def md5_hex(s: str) -> str:
    return _md5(s.encode("utf-8")).hexdigest()


# ---------------------------------------------------------------------------
# Per-club configuration (ENV only — mirrors payment.club_credentials)
# ---------------------------------------------------------------------------
def _env(key: str, file_vals: dict[str, str]) -> str | None:
    """Real environment variables win over .env, same as the Pelecard reader."""
    v = os.environ.get(key)
    if v is None:
        v = file_vals.get(key)
    v = (v or "").strip()
    return v or None


def ttlock_config(club) -> dict | None:
    """Resolve a club's TTLock settings from the environment, or None if the club
    has no lock configured (→ the feature is skipped for that club).

    Per-club:  TTLOCK_<CLUBID>_LOCK_ID, _USERNAME, _PASSWORD or _PASSWORD_MD5,
               optional _CLIENT_ID / _CLIENT_SECRET / _EARLY_ENTRY_MIN overrides.
    Global:    TTLOCK_API_BASE, TTLOCK_CLIENT_ID, TTLOCK_CLIENT_SECRET,
               TTLOCK_EARLY_ENTRY_MIN.
    """
    if not club or club.id is None:
        return None
    fv = _env_file_values()
    cid = str(club.id)
    prefix = f"TTLOCK_{cid}_"

    lock_id = _env(prefix + "LOCK_ID", fv)
    username = _env(prefix + "USERNAME", fv)
    if not lock_id or not username:
        return None  # no lock / account for this club → skip

    client_id = _env(prefix + "CLIENT_ID", fv) or _env("TTLOCK_CLIENT_ID", fv)
    client_secret = _env(prefix + "CLIENT_SECRET", fv) or _env("TTLOCK_CLIENT_SECRET", fv)
    if not client_id or not client_secret:
        logger.warning("TTLock: club %s has LOCK_ID/USERNAME but no client credentials", cid)
        return None

    pwd_md5 = _env(prefix + "PASSWORD_MD5", fv)
    if not pwd_md5:
        plain = _env(prefix + "PASSWORD", fv)
        pwd_md5 = md5_hex(plain) if plain else None
    if not pwd_md5:
        logger.warning("TTLock: club %s has no password configured", cid)
        return None

    try:
        lock_id_int = int(lock_id)
    except ValueError:
        logger.warning("TTLock: club %s LOCK_ID is not numeric: %r", cid, lock_id)
        return None

    early = _env(prefix + "EARLY_ENTRY_MIN", fv) or _env("TTLOCK_EARLY_ENTRY_MIN", fv)
    try:
        early_min = int(early) if early else _DEFAULT_EARLY_ENTRY_MIN
    except ValueError:
        early_min = _DEFAULT_EARLY_ENTRY_MIN

    return {
        "club_id": club.id,
        "api_base": (_env("TTLOCK_API_BASE", fv) or _DEFAULT_API_BASE).rstrip("/"),
        "client_id": client_id,
        "client_secret": client_secret,
        "username": username,
        "password_md5": pwd_md5,
        "lock_id": lock_id_int,
        "early_entry_min": early_min,
    }


# ---------------------------------------------------------------------------
# Time math — booked slot → hour-granular offline-PIN window (epoch ms)
# ---------------------------------------------------------------------------
def _floor_hour_ms(ms: int) -> int:
    return (ms // _HOUR_MS) * _HOUR_MS


def _ceil_hour_ms(ms: int) -> int:
    return -(-ms // _HOUR_MS) * _HOUR_MS


def _slot_bounds_ms(order) -> tuple[int, int] | None:
    """Absolute [start, end] epoch-ms of the booking's slot, from its local
    (Asia/Jerusalem) wall-clock time."""
    slot = getattr(order, "slot", None)
    tmpl = slot.rental_template if slot else None
    if not slot or not slot.curdate or slot.hour is None:
        return None
    offset = (tmpl.minutes_offset or 0) if tmpl else 0
    start = datetime(
        slot.curdate.year, slot.curdate.month, slot.curdate.day,
        slot.hour, offset, tzinfo=CLUB_TZ,
    )
    end = start + timedelta(hours=1)
    return int(start.timestamp() * 1000), int(end.timestamp() * 1000)


def pin_window_ms(order, early_entry_min: int) -> tuple[int, int] | None:
    """The offline PIN's validity window, hour-rounded in local time. Early entry is
    applied to the start before flooring, so with on-the-hour slots a non-zero early
    entry opens the previous whole hour (offline PINs are only hour-granular). Set
    TTLOCK_EARLY_ENTRY_MIN=0 for exact hour windows."""
    bounds = _slot_bounds_ms(order)
    if not bounds:
        return None
    start_ms, end_ms = bounds
    return _floor_hour_ms(start_ms - early_entry_min * 60_000), _ceil_hour_ms(end_ms)


def gate_code_validity_text(order) -> str:
    """Human (Hebrew) validity window for the stored PIN, e.g. 'משעה 18:00 עד 19:00'.
    Best-effort; returns '' if it can't be computed."""
    try:
        cfg = ttlock_config(order.slot.rental_template.club)
        early = cfg["early_entry_min"] if cfg else _DEFAULT_EARLY_ENTRY_MIN
        win = pin_window_ms(order, early)
        if not win:
            return ""
        s = datetime.fromtimestamp(win[0] / 1000, CLUB_TZ)
        e = datetime.fromtimestamp(win[1] / 1000, CLUB_TZ)
        return f"משעה {s:%H:%M} עד {e:%H:%M}"
    except Exception:
        return ""


# ---------------------------------------------------------------------------
# Minimal TTLock cloud client, with an in-process per-club token cache
# ---------------------------------------------------------------------------
class _TTLockError(Exception):
    def __init__(self, errcode: int, errmsg: str):
        super().__init__(f"TTLock [{errcode}] {errmsg}")
        self.errcode = errcode


class _Client:
    """One per club (keyed by club id). Holds the OAuth token in memory; a token is
    always re-derivable from the env credentials, so nothing is persisted."""

    def __init__(self, cfg: dict):
        self.cfg = cfg
        self._token: dict | None = None  # {access, refresh, expires_at}

    # --- transport ---
    def _post(self, path: str, params: dict) -> dict:
        data = {k: v for k, v in params.items() if v is not None}
        resp = httpx.post(self.cfg["api_base"] + path, data=data, timeout=20)
        resp.raise_for_status()
        js = resp.json()
        errcode = js.get("errcode")
        if isinstance(errcode, int) and errcode != 0:
            raise _TTLockError(errcode, js.get("errmsg") or js.get("description") or "unknown")
        if path.startswith("/oauth2") and js.get("access_token") is None and js.get("errmsg"):
            raise _TTLockError(-1, js["errmsg"])
        return js

    # --- auth ---
    def _login(self) -> dict:
        js = self._post("/oauth2/token", {
            "clientId": self.cfg["client_id"],
            "clientSecret": self.cfg["client_secret"],
            "username": self.cfg["username"],
            "password": self.cfg["password_md5"],
        })
        return self._save_token(js)

    def _refresh(self, refresh_token: str) -> dict:
        js = self._post("/oauth2/token", {
            "clientId": self.cfg["client_id"],
            "clientSecret": self.cfg["client_secret"],
            "grant_type": "refresh_token",
            "refresh_token": refresh_token,
        })
        return self._save_token(js)

    def _save_token(self, js: dict) -> dict:
        self._token = {
            "access": js["access_token"],
            "refresh": js.get("refresh_token"),
            "expires_at": time.time() + float(js.get("expires_in") or 7776000),
        }
        return self._token

    def _access_token(self) -> str:
        tok = self._token
        if not tok:
            return self._login()["access"]
        if tok["expires_at"] - time.time() < _REFRESH_MARGIN_S and tok.get("refresh"):
            try:
                return self._refresh(tok["refresh"])["access"]
            except Exception:
                return self._login()["access"]
        return tok["access"]

    def _call(self, endpoint: str, params: dict) -> dict:
        def send():
            return self._post(f"/v3/{endpoint}", {
                "clientId": self.cfg["client_id"],
                "accessToken": self._access_token(),
                "date": int(time.time() * 1000),
                **params,
            })
        try:
            return send()
        except _TTLockError as e:
            if e.errcode in _TOKEN_ERRORS:
                self._login()
                return send()
            raise

    def get_offline_pin(self, start_ms: int, end_ms: int, name: str) -> str:
        """keyboardPwd/get, type 3 (period). Returns the passcode digits."""
        js = self._call("keyboardPwd/get", {
            "lockId": self.cfg["lock_id"],
            "keyboardPwdType": 3,
            "startDate": start_ms,
            "endDate": end_ms,
            "keyboardPwdName": name,
        })
        pwd = js.get("keyboardPwd")
        if not pwd:
            raise _TTLockError(-1, f"no keyboardPwd in response: {js}")
        return str(pwd)


_clients: dict[int, _Client] = {}
_clients_lock = threading.Lock()


def _client_for(cfg: dict) -> _Client:
    with _clients_lock:
        c = _clients.get(cfg["club_id"])
        if c is None:
            c = _Client(cfg)
            _clients[cfg["club_id"]] = c
        else:
            c.cfg = cfg  # pick up any env change on restart/reload
        return c


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------
def generate_gate_pin(order, cfg: dict) -> str | None:
    """Mint an offline PIN for the order's slot. Never raises — returns None on any
    failure (missing slot, TTLock down, lock without keypad/clock, …)."""
    try:
        win = pin_window_ms(order, cfg["early_entry_min"])
        if not win:
            logger.warning("TTLock: order %s has no usable slot window", getattr(order, "id", "?"))
            return None
        name = f"BACO {getattr(order, 'order_id', order.id)}"
        pin = _client_for(cfg).get_offline_pin(win[0], win[1], name)
        logger.info("TTLock: minted gate PIN for order %s (club %s, lock %s)",
                    order.id, cfg["club_id"], cfg["lock_id"])
        return pin
    except Exception as exc:
        logger.error("TTLock: failed to mint PIN for order %s: %s", getattr(order, "id", "?"), exc)
        return None


def ensure_gate_code(order, db) -> str | None:
    """Return the order's gate PIN, minting and storing it once if the club has
    TTLock configured. Idempotent and safe to call from any finalization path or
    from the booking list. Never raises."""
    try:
        existing = getattr(order, "gate_code", None)
        if existing:
            return existing
        slot = getattr(order, "slot", None)
        club = slot.rental_template.club if slot and slot.rental_template else None
        cfg = ttlock_config(club)
        if not cfg:
            return None
        pin = generate_gate_pin(order, cfg)
        if pin:
            order.gate_code = pin
            db.commit()
        return pin
    except Exception as exc:
        logger.error("TTLock: ensure_gate_code failed for order %s: %s", getattr(order, "id", "?"), exc)
        try:
            db.rollback()
        except Exception:
            pass
        return None
